    {
        var stock = N(1, 1, 1);
        var (result, dispenser) = Withdraw(80, 0, 80, stock);

        Assert.Equal(AtmStatus.Ok, result.Status);
        Assert.Equal(new AccountState(0, 80), result.Account);
        Assert.Equal(NoteCounts.None, dispenser.Stock);
    }
}
