        { 110, 0, N(5, 5, 5), null, 110, AtmStatus.InsufficientFunds, NoteCounts.None, 0, 110, 0 },
        { 250, 150, N(5, 5, 5), null, 60, AtmStatus.DailyLimitExceeded, NoteCounts.None, 0, 250, 150 },
